// === Tab: mySketch ===
var particles = [];
var colors;
var startColor;
var maxConnections = 1;
var connectionDist = 40;
var particleSize = 1;

function setup() {
		createCanvas(windowWidth, windowHeight);
    angleMode(DEGREES);
    colorMode(HSB, 360);

	  particleNum = windowWidth/5
		colors = [280, 1, 40, 140, 180, 240, 300, 340];
		startColor = random(colors);
		endColor = startColor + 40;
		if(endColor > 360) endColor = abs(360 - endColor);
		background(0)

		for(let x=0; x<particleNum; x++) {
				particles.push(new Particle(random(windowWidth), random(windowHeight)));	
		}
}

function Connection(x1, y1, x2, y2) {
    this.start = createVector(x1, y1);
    this.end = createVector(x2, y2);

    this.show = function(num) {
				maxConnections = max(num, maxConnections);
        var color = lerp(startColor, endColor, num/maxConnections);
        stroke(color, 360, 360);
				strokeWeight(particleSize);
        line(this.start.x, this.start.y, this.end.x, this.end.y);
    }

}

function Particle(x, y) {
    this.off = x;
    this.steer = 0;
    this.vel = createVector(0, 0);

    this.loc = createVector(x, y);

    this.life = 255;

    this.connections = [];
    this.numConnect = 1;

    this.show = function() {
        noStroke();
        fill(startColor, 360, 360);
        ellipse(this.loc.x, this.loc.y, particleSize);
    }

    this.update = function() {
        this.off += 0.0005;
        this.steer = noise(this.off) * 360; 
        this.vel = p5.Vector.fromAngle(this.steer);
        this.vel.setMag(1);
        this.loc.add(this.vel);

        // this.life -= 1;

        for(var i = 0; i < this.connections.length; i++) {
            this.connections[i].show(this.numConnect);
        }

        this.connections = [];
        this.numConnect = 0;

				this.checkEdges()
    }

		this.checkEdges = function() {
				if(this.loc.x > windowWidth || this.loc.x < 0 || this.loc.y > windowHeight || this.loc.y < 0) {
						this.loc = createVector(random(windowWidth), random(windowHeight))
				}
		}

    this.connect = function(p) {
        if(dist(this.loc.x, this.loc.y, p.loc.x, p.loc.y) < connectionDist) {
            this.connections.push(new Connection(this.loc.x ,this.loc.y, p.loc.x, p.loc.y));
           	this.numConnect++;
        }
    }
}

function draw() {

    for(var i = 0; i < particles.length; i++) {
        particles[i].show();
        particles[i].update();
        for(var j = i+1; j < particles.length; j++) {
            particles[i].connect(particles[j]);
        }
    }
		maxConnections = 1;

}

